INSERT INTO _migration_503_expected (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_bghl_greetings_s2_001', 'topic_bece_ghlang_greetings', 'subj_bece_gh_lang', 'exam_bece', NULL, NULL, 'In Twi, the greeting “Maakye” is used at which time of day?', 'multiple_choice', NULL, '["A. In the morning","B. In the afternoon","C. In the evening","D. At midnight"]', 'A', 'Maakye is the Akan morning greeting, used from dawn until about midday. The afternoon greeting is “Maaha” and the evening greeting is “Maadwo”, so the other options belong to different parts of the day. Therefore the correct answer is A: In the morning.', 'easy', '2', '1', '60', NULL, NULL, '1', NULL, NULL, 'Identify', 'AO1', NULL, NULL, 'board_waec'),
('q_bghl_greetings_s2_002', 'topic_bece_ghlang_greetings', 'subj_bece_gh_lang', 'exam_bece', NULL, NULL, 'What does the Twi expression “Akwaaba” mean?', 'multiple_choice', NULL, '["A. Goodbye","B. Welcome","C. Thank you","D. I am sorry"]', 'B', 'Akwaaba means “welcome” and is said to a person who has just arrived. A farewell is “Nante yie” and thanks is “Medaase”, so those options describe different expressions. Therefore the correct answer is B: Welcome.', 'easy', '2', '1', '60', NULL, NULL, '1', NULL, NULL, 'State', 'AO1', NULL, NULL, 'board_waec'),
('q_bghl_greetings_s2_003', 'topic_bece_ghlang_greetings', 'subj_bece_gh_lang', 'exam_bece', NULL, NULL, 'After receiving a gift, Kofi says “Medaase” to the giver. What has Kofi said?', 'multiple_choice', NULL, '["A. Good morning","B. Welcome","C. Thank you","D. How are you?"]', 'C', 'Medaase (me da wo ase) is the Akan way of saying “thank you”. “Good morning” is Maakye, “welcome” is Akwaaba and “how are you?” is Ɛte sɛn?, so none of the distractors expresses gratitude. Therefore the correct answer is C: Thank you.', 'easy', '2', '1', '60', NULL, NULL, '1', NULL, NULL, 'Identify', 'AO1', NULL, NULL, 'board_waec'),
('q_bghl_greetings_s2_004', 'topic_bece_ghlang_greetings', 'subj_bece_gh_lang', 'exam_bece', NULL, NULL, 'A pupil answers a greeting with the respectful reply “Yaa agya”. To whom is the pupil most likely responding?', 'multiple_choice', NULL, '["A. An elderly woman","B. A chief or grandparent","C. A younger sibling","D. An elderly man"]', 'D', '“Yaa agya” is the respectful greeting response given to an elderly man (agya means father). An elderly woman receives “Yaa ɛna”, and a chief or grandparent receives “Yaa nana”; a younger sibling is addressed without these honorific replies. Therefore the correct answer is D: An elderly man.', 'medium', '3', '1', '90', NULL, NULL, '1', NULL, NULL, 'Determine', 'AO2', NULL, NULL, 'board_waec'),
('q_bghl_greetings_s2_005', 'topic_bece_ghlang_greetings', 'subj_bece_gh_lang', 'exam_bece', NULL, NULL, 'What is the appropriate response to the Twi question “Ɛte sɛn?”', 'multiple_choice', NULL, '["A. “Me ho yɛ” (I am fine)","B. “Nante yie” (farewell)","C. “Akwaaba” (welcome)","D. “Maadwo” (good evening)"]', 'A', 'Ɛte sɛn? means “How are you?”, and the usual reply is “Me ho yɛ” — I am fine. Nante yie is a farewell, Akwaaba means welcome and Maadwo is the evening greeting, so they answer different situations. Therefore the correct answer is A: “Me ho yɛ” (I am fine).', 'medium', '3', '1', '90', NULL, NULL, '1', NULL, NULL, 'Determine', 'AO2', NULL, NULL, 'board_waec'),
('q_bghl_greetings_s2_006', 'topic_bece_ghlang_greetings', 'subj_bece_gh_lang', 'exam_bece', NULL, NULL, 'What does the Twi farewell “Nante yie” literally mean?', 'multiple_choice', NULL, '["A. “Sleep well”","B. “Walk well” — a farewell wish","C. “Eat well”","D. “Come back soon”"]', 'B', 'Nante yie literally means “walk well” and is said when people part, wishing the traveller a safe journey. It is a farewell expression, not a wish about sleeping, eating or returning. Therefore the correct answer is B: “Walk well” — a farewell wish.', 'medium', '3', '1', '90', NULL, NULL, '1', NULL, NULL, 'State', 'AO1', NULL, NULL, 'board_waec'),
('q_bghl_greetings_s2_007', 'topic_bece_ghlang_greetings', 'subj_bece_gh_lang', 'exam_bece', NULL, NULL, 'Which Akan title is correctly used to address or refer to a traditional ruler or a grandparent?', 'multiple_choice', NULL, '["A. Sewaa","B. Wɔfa","C. Nana","D. Onua"]', 'C', 'Nana is the honorific title for a chief, a king or a grandparent. Sewaa is a paternal aunt (father’s sister), wɔfa is a maternal uncle (mother’s brother) and onua is a sibling, so none of those titles fits a ruler or grandparent. Therefore the correct answer is C: Nana.', 'hard', '4', '1', '120', NULL, NULL, '1', NULL, NULL, 'Identify', 'AO2', NULL, NULL, 'board_waec'),
('q_bghl_greetings_s2_008', 'topic_bece_ghlang_greetings', 'subj_bece_gh_lang', 'exam_bece', NULL, NULL, 'Which Twi expression is used to say “please” when making a polite request?', 'multiple_choice', NULL, '["A. “Meda wo ase”","B. “Nante yie”","C. “Maakye”","D. “Me pa wo kyɛw”"]', 'D', 'Me pa wo kyɛw (often heard as mepaakyɛw) literally means “I beg you” and is the polite way to say “please” in Twi. Meda wo ase expresses thanks, Nante yie is a farewell and Maakye is a morning greeting. Therefore the correct answer is D: “Me pa wo kyɛw”.', 'hard', '4', '1', '120', NULL, NULL, '1', NULL, NULL, 'Identify', 'AO2', NULL, NULL, 'board_waec');
INSERT INTO _migration_503_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM _migration_503_expected e JOIN questions q ON q.id = e.id WHERE NOT (q.topic_id IS e.topic_id AND q.subject_id IS e.subject_id AND q.exam_type_id IS e.exam_type_id AND q.paper_type_id IS e.paper_type_id AND q.past_paper_id IS e.past_paper_id AND q.question_text IS e.question_text AND q.question_type IS e.question_type AND q.round_type IS e.round_type AND q.options IS e.options AND q.correct_answer IS e.correct_answer AND q.explanation IS e.explanation AND q.difficulty IS e.difficulty AND q.points IS e.points AND q.marks IS e.marks AND q.time_limit IS e.time_limit AND q.question_number IS e.question_number AND q.section IS e.section AND q.is_compulsory IS e.is_compulsory AND q.image_url IS e.image_url AND q.syllabus_topic_id IS e.syllabus_topic_id AND q.command_word IS e.command_word AND q.assessment_objective IS e.assessment_objective AND q.source_paper_code IS e.source_paper_code AND q.source_question_number IS e.source_question_number AND q.exam_board_id IS e.exam_board_id)) AND NOT EXISTS (SELECT 1 FROM _migration_503_expected e JOIN question_content_releases r ON r.question_id = e.id WHERE NOT (r.batch_id IS 'bece-ghlang-sprint2-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep practice content aligned to Ghana''s published NaCCA Common Core Programme Ghanaian Language curriculum; not official WAEC or NaCCA examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://nacca.gov.gh/common-core-programme-ccp/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) SELECT id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id FROM _migration_503_expected e WHERE NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = e.id);
INSERT INTO question_content_releases (question_id, batch_id, quality_assurance, release_channel, content_label, source_url, official_exam_board_content, feedback_enabled) SELECT e.id, 'bece-ghlang-sprint2-001', 'automated_beta', 'beta', 'Original BrillaPrep practice content aligned to Ghana''s published NaCCA Common Core Programme Ghanaian Language curriculum; not official WAEC or NaCCA examination material. Use the enabled feedback channel to report corrections.', 'https://nacca.gov.gh/common-core-programme-ccp/', 0, 1 FROM _migration_503_expected e WHERE NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = e.id);
INSERT INTO _migration_503_guard(valid) SELECT CASE WHEN (SELECT COUNT(*) FROM questions q JOIN _migration_503_expected e ON e.id = q.id AND q.topic_id IS e.topic_id AND q.subject_id IS e.subject_id AND q.exam_type_id IS e.exam_type_id AND q.paper_type_id IS e.paper_type_id AND q.past_paper_id IS e.past_paper_id AND q.question_text IS e.question_text AND q.question_type IS e.question_type AND q.round_type IS e.round_type AND q.options IS e.options AND q.correct_answer IS e.correct_answer AND q.explanation IS e.explanation AND q.difficulty IS e.difficulty AND q.points IS e.points AND q.marks IS e.marks AND q.time_limit IS e.time_limit AND q.question_number IS e.question_number AND q.section IS e.section AND q.is_compulsory IS e.is_compulsory AND q.image_url IS e.image_url AND q.syllabus_topic_id IS e.syllabus_topic_id AND q.command_word IS e.command_word AND q.assessment_objective IS e.assessment_objective AND q.source_paper_code IS e.source_paper_code AND q.source_question_number IS e.source_question_number AND q.exam_board_id IS e.exam_board_id) = 8 AND (SELECT COUNT(*) FROM question_content_releases r JOIN _migration_503_expected e ON e.id = r.question_id WHERE r.batch_id IS 'bece-ghlang-sprint2-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep practice content aligned to Ghana''s published NaCCA Common Core Programme Ghanaian Language curriculum; not official WAEC or NaCCA examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://nacca.gov.gh/common-core-programme-ccp/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1) = 8 AND (SELECT COUNT(*) FROM questions q JOIN topics t ON t.id = q.topic_id AND t.subject_id = q.subject_id JOIN _migration_503_expected e ON e.id = q.id) = 8 AND (SELECT COUNT(*) FROM questions q JOIN subjects s ON s.id = q.subject_id AND s.exam_type_id = q.exam_type_id JOIN _migration_503_expected e ON e.id = q.id) = 8 THEN 1 ELSE 0 END;
